  const [authReady, setAuthReady] = useState(false);
  const [authBusy, setAuthBusy] = useState(false);
  const [authError, setAuthError] = useState("");
  const [users, setUsers] = useState<ManagedUser[]>([]);
  const [usersLoading, setUsersLoading] = useState(false);
  const [usersMessage, setUsersMessage] = useState("");
  const [showCreateUser,setShowCreateUser]=useState(false);
  const [permissionUser,setPermissionUser]=useState<ManagedUser|null>(null);
  const [employeeUserQuery,setEmployeeUserQuery]=useState("");
  const [selectedUserEmployeeId,setSelectedUserEmployeeId]=useState("");
  const [linkingUser,setLinkingUser]=useState<ManagedUser|null>(null);
  const [permissionModule,setPermissionModule]=useState("Dirección General");
  const [catalogs,setCatalogs]=useState<ProjectCatalogs>(emptyCatalogs);
  const [catalogMessage,setCatalogMessage]=useState("");
  const [showCatalogForm,setShowCatalogForm]=useState<CatalogType|null>(null);
  const [editingCatalogItem,setEditingCatalogItem]=useState<CatalogItem|null>(null);
  const [activeCatalogType,setActiveCatalogType]=useState<CatalogType>("supplier");
  const [catalogQuery,setCatalogQuery]=useState("");
  const [expandedDirection,setExpandedDirection]=useState("Dirección General");
  const [recentSections,setRecentSections]=useState<string[]>([]);
  const [technicalProjects, setTechnicalProjects] = useState<TechnicalProject[]>([]);
  const [technicalLoading, setTechnicalLoading] = useState(false);
  const [technicalMessage, setTechnicalMessage] = useState("");
  const [showTechnicalForm, setShowTechnicalForm] = useState(false);
  const [editingTechnical, setEditingTechnical] = useState<TechnicalProject | null>(null);
  const [measurements,setMeasurements]=useState<Measurement[]>([]);
  const [measurementsLoading,setMeasurementsLoading]=useState(false);
  const [measurementMessage,setMeasurementMessage]=useState("");
  const [showMeasurementForm,setShowMeasurementForm]=useState(false);
  const [auditMeasurement,setAuditMeasurement]=useState<Measurement|null>(null);
  const [section, setSection] = useState("Resumen");
  const [dashboardPanel,setDashboardPanel]=useState<"Pendientes"|"Alertas"|"Proyectos"|"Actividad">("Pendientes");
  const [dashboardStatus,setDashboardStatus]=useState("Todos");
  const [uiDensity,setUiDensity]=useState<"comfortable"|"compact">("comfortable");
  const [uiSettingsOpen,setUiSettingsOpen]=useState(false);
  const [showSecondaryMetrics,setShowSecondaryMetrics]=useState(false);
  const [showModuleFilters,setShowModuleFilters]=useState(true);
  const [showContextHelp,setShowContextHelp]=useState(false);
  const [experienceMode,setExperienceMode]=useState<"simple"|"advanced">("simple");
