  async function handleAuth(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setAuthBusy(true);
    setAuthError("");
    const fd = new FormData(e.currentTarget);
    const username = String(fd.get("username") || "").trim();
    const password = String(fd.get("password") || "");
    if (!username || username.length < 3) {
      setAuthError("El usuario debe tener al menos 3 caracteres.");
      setAuthBusy(false);
      return;
    }
    if (password.length < 6) {
      setAuthError("La contraseña debe tener al menos 6 caracteres.");
      setAuthBusy(false);
      return;
    }
    const response = await fetch("/api/auth/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username, password }),
    });
    const result = await response.json();
    if (!response.ok) setAuthError(result.error || "No fue posible completar la solicitud.");
    else setCurrentUser(result.user);
    setAuthBusy(false);
  }

  async function logout() {
    await fetch("/api/auth/logout", { method: "POST" });
    setCurrentUser(null);
  }

  async function updateUser(user: ManagedUser, changes: Partial<ManagedUser>) {
    setUsersMessage("");
    const updated = { ...user, ...changes };
    const suspensionReason = changes.active === false ? window.prompt("Motivo de la suspensión:", "Suspendido por el administrador") || "" : "";
    const response = await fetch("/api/users", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: updated.id, role: updated.role, area: updated.area, department: updated.department || "", active: updated.active, suspensionReason }) });
    const result = await response.json();
    if (!response.ok) setUsersMessage(result.error || "No se pudo actualizar el usuario.");
    else { setUsers(previous => previous.map(item => item.id === updated.id ? updated : item));setPermissionUser(current=>current?.id===updated.id?updated:current); setUsersMessage("Cambios guardados correctamente."); }
  }
  async function resetUserPassword(user:ManagedUser){const password=window.prompt(`Nueva contraseña temporal para @${user.username}:`);if(password===null)return;if(password.length<8){setUsersMessage("La contraseña temporal debe tener al menos 8 caracteres.");return;}const confirmation=window.prompt("Confirme la contraseña temporal:");if(confirmation!==password){setUsersMessage("Las contraseñas no coinciden.");return;}const response=await fetch("/api/users",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:user.id,action:"RESET_PASSWORD",tempPassword:password})});const result=await response.json();if(!response.ok){setUsersMessage(result.error||"No fue posible restablecer la contraseña.");return;}setUsers(items=>items.map(item=>item.id===user.id?{...item,must_change_password:true}:item));setUsersMessage(`Contraseña temporal asignada a @${user.username}. Deberá cambiarla al iniciar sesión.`);}

  function enablePermissionParents(permissions:Permissions,key:keyof Permissions){let parent=permissionParents[key];while(parent){permissions[parent]=true;parent=permissionParents[parent]}} function disablePermissionChildren(permissions:Permissions,key:keyof Permissions){for(const [child,parent] of Object.entries(permissionParents) as [keyof Permissions,keyof Permissions][])if(parent===key){permissions[child]=false;disablePermissionChildren(permissions,child)}}
  function permissionGroupVisible(groupTitle:string){return Boolean(permissionDirections.find(direction=>direction.name===permissionModule)?.groups.includes(groupTitle))}
  async function updatePermissions(user:ManagedUser,key:keyof Permissions,enabled:boolean){const permissions={...(user.permissions||{}),[key]:enabled};if(enabled)enablePermissionParents(permissions,key);else disablePermissionChildren(permissions,key);const response=await fetch("/api/users",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:user.id,permissions})});const result=await response.json();if(!response.ok)setUsersMessage(result.error||"No se pudieron actualizar los permisos.");else{setUsers(items=>items.map(item=>item.id===user.id?{...item,permissions}:item));setPermissionUser(current=>current?.id===user.id?{...current,permissions}:current);setUsersMessage("Permisos guardados correctamente.");}}
  async function updateHrScope(user:ManagedUser,unitId:string){const response=await fetch("/api/users",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:user.id,action:"SET_HR_SCOPE",organizationScopeUnitId:unitId||null})});const result=await response.json();if(!response.ok){setUsersMessage(result.error||"No se pudo actualizar la unidad bajo su cargo.");return;}const unit=organizationUnits.find(item=>item.id===unitId);const updated={...user,organization_scope_unit_id:unitId||null,organization_scope_unit:unit?.unit_name||null,department:unit?.unit_name||""};setUsers(items=>items.map(item=>item.id===user.id?updated:item));setPermissionUser(updated);setUsersMessage("Alcance jerárquico guardado correctamente.");}

  async function createManagedUser(payload:{employeeId:string;username:string;password:string;role:string;permissions:Record<string,boolean>}){setUsersMessage("");const permissions={...payload.permissions} as Permissions;for(const key of Object.keys(permissions) as (keyof Permissions)[])if(permissions[key])enablePermissionParents(permissions,key);const response=await fetch("/api/users",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...payload,permissions})});const result=await response.json();if(!response.ok)return result.error||"No fue posible crear el usuario.";setShowCreateUser(false);setSelectedUserEmployeeId("");setEmployeeUserQuery("");setUsers(items=>[...items,result.user]);setHrEmployees(items=>items.map(item=>item.id===payload.employeeId?{...item,app_user_id:result.user.id}:item));setUsersMessage("Usuario creado y vinculado al empleado activo.");}
  async function linkUserEmployee(){if(!linkingUser||!selectedUserEmployeeId)return;const response=await fetch("/api/users",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:linkingUser.id,employeeId:selectedUserEmployeeId})});const result=await response.json();if(!response.ok){setUsersMessage(result.error||"No fue posible vincular el empleado.");return;}setUsers(items=>items.map(item=>item.id===linkingUser.id?{...item,...result.user}:item));setHrEmployees(items=>items.map(item=>({...item,app_user_id:item.id===selectedUserEmployeeId?linkingUser.id:item.app_user_id===linkingUser.id?null:item.app_user_id})));setLinkingUser(null);setSelectedUserEmployeeId("");setEmployeeUserQuery("");setUsersMessage("Empleado vinculado y unidad organizacional actualizada.");}

  async function saveCatalogItem(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(!showCatalogForm)return;const fd=new FormData(e.currentTarget);const payload={type:showCatalogForm,id:editingCatalogItem?.id,code:String(fd.get("code")||""),name:String(fd.get("name")||""),description:String(fd.get("description")||""),active:editingCatalogItem?.active??true};const response=await fetch("/api/catalogs",{method:editingCatalogItem?"PATCH":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok){setCatalogMessage(result.error||"No fue posible guardar el registro.");return;}setShowCatalogForm(null);setEditingCatalogItem(null);setCatalogMessage(editingCatalogItem?"Cuenta presupuestaria actualizada correctamente.":"Registro agregado correctamente.");await loadCatalogs();}
  async function toggleCatalog(type:string,item:CatalogItem){const response=await fetch("/api/catalogs",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({type,id:item.id,code:item.code||"",name:item.name||"",description:item.description||"",active:!item.active})});const result=await response.json();if(!response.ok)setCatalogMessage(result.error||"No fue posible actualizar el registro.");else{setCatalogMessage("Catálogo actualizado correctamente.");await loadCatalogs();}}

  async function changeFirstPassword(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setAuthBusy(true);setAuthError("");const fd=new FormData(e.currentTarget);const password=String(fd.get("password")||"");const confirmation=String(fd.get("confirmation")||"");if(password.length<8){setAuthError("La nueva contraseña debe tener al menos 8 caracteres.");setAuthBusy(false);return;}if(password!==confirmation){setAuthError("Las contraseñas no coinciden.");setAuthBusy(false);return;}const response=await fetch("/api/auth/change-password",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({password})});const result=await response.json();if(!response.ok)setAuthError(result.error||"No fue posible cambiar la contraseña.");else setCurrentUser(result.user);setAuthBusy(false);}

  function canView(key:keyof Permissions){const confidentialityKey=key==="editar_recursos_humanos"?"modificar_empleados":key==="aprobar_recursos_humanos"?"aprobar_acciones_personal":key;return currentUser?.role==="Administrador"||Boolean(currentUser?.permissions?.[confidentialityKey as keyof Permissions]);}
  function canUseGranularPermission(key:keyof Permissions){if(currentUser?.role==="Administrador")return true;return Object.prototype.hasOwnProperty.call(currentUser?.permissions||{},key)?Boolean(currentUser?.permissions?.[key]):canView(permissionParents[key]||key);}
  function canViewReport(type:ReportType){const option=reportOptions.find(item=>item.value===type);return option?canUseGranularPermission(option.permission):false;}
  function canSeeModule(module:DirectionModule,direction:InstitutionalDirection){if(currentUser?.role==="Administrador")return true;if(module.adminOnly)return false;if(direction.accessPermission&&Object.prototype.hasOwnProperty.call(currentUser?.permissions||{},direction.accessPermission)&&!currentUser?.permissions?.[direction.accessPermission])return false;if(module.roles&&!module.roles.includes(currentUser?.role||""))return false;if(module.permission&&!canView(module.permission))return false;if(direction.area&&module.permission===undefined)return currentUser?.area===direction.area;return true;}

  async function createMeasurement(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setMeasurementMessage("");const fd=new FormData(e.currentTarget);const response=await fetch("/api/cubicaciones",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({projectId:fd.get("projectId"),amount:Number(fd.get("amount")),progress:Number(fd.get("progress")),description:String(fd.get("description"))})});const result=await response.json();if(!response.ok){setMeasurementMessage(result.error||"No se pudo registrar la cubicación.");return;}setShowMeasurementForm(false);setMeasurementMessage(`Cubicación ${result.code} registrada correctamente.`);await synchronizeProjectData();}

  async function transitionMeasurement(measurement:Measurement,action:"ADVANCE"|"RETURN"){const next=action==="RETURN"?(measurement.status==="Revisada"?"Cubicada":"Revisada"):(measurement.status==="Cubicada"?"Revisada":measurement.status==="Revisada"?"Libramiento":measurement.status==="Libramiento"?"Pagada":null);if(!next)return;const comments=window.prompt(action==="RETURN"?`Observación obligatoria para devolver a ${next}:`:`Comentario para avanzar a ${next}:`)||"";if(action==="RETURN"&&comments.trim().length<5){setMeasurementMessage("Debe indicar una observación para devolver la cubicación.");return;}const response=await fetch("/api/cubicaciones",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:measurement.id,action,comments})});const result=await response.json();if(!response.ok)setMeasurementMessage(result.error||"No se pudo cambiar el estado de la cubicación.");else{setMeasurementMessage(action==="RETURN"?`Cubicación devuelta a ${next}.`:`Cubicación avanzada a ${next}.`);await synchronizeProjectData();}}
  async function correctPaidMeasurement(measurement:Measurement){if(currentUser?.role!=="Administrador")return;const value=window.prompt(`Monto pagado actual: ${money(Number(measurement.amount))}\nIndique el monto correcto:`,String(measurement.amount));if(value===null)return;const amount=Number(value);if(!Number.isFinite(amount)||amount<=0){setMeasurementMessage("El monto corregido debe ser mayor que cero.");return;}const comments=window.prompt("Motivo obligatorio de la corrección:")||"";if(comments.trim().length<5){setMeasurementMessage("Debe indicar el motivo de la corrección.");return;}const response=await fetch("/api/cubicaciones",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:measurement.id,action:"CORRECT_PAYMENT",amount,comments})});const result=await response.json();if(!response.ok){setMeasurementMessage(result.error||"No fue posible corregir el pago.");return;}setMeasurementMessage(`Pago corregido de ${money(Number(result.previous_amount))} a ${money(Number(result.amount))}.`);await synchronizeProjectData();}
  async function correctProjectProgress(measurement:Measurement){if(currentUser?.role!=="Administrador")return;const project=technicalProjects.find(item=>item.id===measurement.project_id);const current=Number(project?.work_progress||0);const value=window.prompt(`Avance físico actual de la obra: ${current}%\nIndique el porcentaje correcto (0 a 100):`,String(current));if(value===null)return;const progress=Number(value);if(!Number.isFinite(progress)||progress<0||progress>100){setMeasurementMessage("El avance físico debe estar entre 0 y 100 %.");return;}const comments=window.prompt("Motivo obligatorio del cambio de avance físico:")||"";if(comments.trim().length<5){setMeasurementMessage("Debe indicar el motivo del cambio.");return;}const response=await fetch("/api/cubicaciones",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:measurement.id,action:"CORRECT_PROGRESS",progress,comments})});const result=await response.json();if(!response.ok){setMeasurementMessage(result.error||"No fue posible cambiar el avance físico.");return;}setMeasurementMessage(`Avance físico actualizado de ${Number(result.previous_progress)}% a ${Number(result.progress)}%.`);await synchronizeProjectData();}
  function canAdvanceMeasurement(status:Measurement["status"]){if(currentUser?.role==="Administrador")return status!=="Pagada";const key=status==="Cubicada"?"revisar_cubicaciones":status==="Revisada"?"libramiento_cubicaciones":status==="Libramiento"?"pagar_cubicaciones":null;return key?Boolean(currentUser?.permissions?.[key as keyof Permissions]):false;}
  function canReturnMeasurement(status:Measurement["status"]){if(!["Revisada","Libramiento"].includes(status))return false;if(currentUser?.role==="Administrador")return true;const key=status==="Revisada"?"revisar_cubicaciones":"libramiento_cubicaciones";return Boolean(currentUser?.permissions?.[key]);}
