                <div className="notification-list">{notificationsLoading?<div className="notification-empty">Actualizando alertas…</div>:notifications.length===0?<div className="notification-empty">No existen notificaciones pendientes.</div>:notifications.map(item=><button className={`${item.read_at?"read":""} severity-${item.severity||"low"}`} key={item.id} onClick={()=>markNotificationRead(item)}><i>{({CUBICACION:"▧",PRESUPUESTO:"$",CONTRATO:"▤",OBRA:"⌁",PAGO:"✓",DOCUMENTO:"▣"})[item.notification_type]||"▣"}</i><div><span>{readableText(item.notification_type,"NOTIFICACIÓN")}</span><strong>{item.title||"Notificación institucional"}</strong><p>{item.message||"Sin detalle disponible"}</p><small>{new Date(item.created_at).toLocaleString("es-DO",{dateStyle:"medium",timeStyle:"short"})} · Ir a {item.action_section||"Resumen"}</small></div>{!item.read_at&&<b/>}</button>)}</div>
